"""Where a session came from: the credential that started it (web app,
API key, CLI) or the trigger that fired (react, mention, cron, code
review). Never taken from a request body."""

SessionStatus = Literal["queued", "preparing", "running", "idle", "closed"]
"""Where the session is. `queued` while a message waits for a worker,
`preparing` while its environment is set up, `running` while the agent
works, `idle` when every message has been answered and the session can
take another, and `closed` when it can take no more. `closed` is
permanent."""

SessionSummarySource = Literal["prompt", "generated", "user"]
"""Where a session's summary came from."""


