class StartAgentSessionRequest(EllipsisModel):
    """Start a session from a saved agent. The body takes the fields of POST
    /v1/sessions, all optional, plus `input`. The session starts from the
    agent's `session` settings: each field you send replaces the agent's value for that field,
    and each field you leave out keeps it. `metadata` is the exception: it is
    merged into the agent's key by key, and a `null` value removes a key.
    Other lists and maps, and `environment`, are replaced whole, and naming the
    other harness replaces the agent's harness. `input` is required when the
    agent declares `input.json_schema` and rejected when it doesn't. Extra keys
    are a 422.
    """

    budget: Union[RunBudget, None] = Field(
        default=None,
        description="Spend limit for this session: `session` is the most it may spend, in US dollars. Omitted, an agent session keeps the agent's limit and a raw session takes the organization's default. Above the organization's per-session ceiling is a 400. `day`, `week`, and `month` are agent-wide limits and are rejected with a 422.",
    )
    claude_code: Union[ClaudeOverrides, None] = Field(
        default=None,
        description="Claude Code options for this session. Sent fields replace the agent's; naming Claude Code on an agent that runs another harness replaces its harness and requires a model. Set at most one of claude_code, codex, or gemini.",
    )
    codex: Union[CodexOverrides, None] = Field(
        default=None,
        description="Codex options for this session. Sent fields replace the agent's; naming Codex on an agent that runs another harness replaces its harness and requires a model. Set at most one of claude_code, codex, or gemini.",
    )
    conversation: Union[SessionConversationConfig_Input, None] = Field(
        default=None,
        description="Conversation settings. Omitted, a raw session is interactive and an agent session keeps the agent's setting. Warmth and prompting are server-owned response fields.",
    )
    environment: Union[str, EnvironmentConfig_Input, None] = Field(
        default=None,
        description="Where the session runs. A STRING is a saved environment's name or `env_...` id, substituted wholesale. An OBJECT is the whole environment for this session, and `{}` is the bare environment. Nothing is merged: what you send is the whole environment. Omitted, a raw session runs in the built-in basic environment and an agent session keeps the agent's own environment.",
    )
    force_rebuild: Union[bool, None] = Field(
        default=None,
        description="Skip the image cache for this session's initial provision: a fresh full build whose snapshot then refreshes the cache for later sessions. The CLI's `--rebuild`.",
    )
    gemini: Union[GeminiOverrides, None] = Field(
        default=None,
        description="Gemini CLI options for this session. Sent fields replace the agent's; naming Gemini CLI on an agent that runs another harness replaces its harness and requires a model. Set at most one of claude_code, codex, or gemini.",
    )
    images: Union[list[ImageAttachment], None] = Field(
        default=None,
        description="Images attached to the first message, base64 inline. Requires the model's `images` capability, listed by `/v1/account/models`. Each becomes an `[Image #N]` placeholder in the prompt and an image block the model sees with it. Up to 10, 5 MiB each; PNG, JPEG, GIF, or WebP.",
    )
    input: Union[dict[str, Any], None] = Field(
        default=None,
        description="The typed payload for an agent that declares input.json_schema. Required when the agent declares a schema; rejected when it does not. Validated against the schema and rendered through input.message, or as formatted JSON if no template is set, and added after the prompt. The rendered message must be non-empty.",
    )
    metadata: Union[dict[str, Union[str, None]], None] = Field(
        default=None,
        description="Metadata merged into the agent's for this session. Each key you send sets that key, a `null` value removes the agent's key, and keys you leave out keep the agent's values.",
    )
    output: Union[OutputConfig, None] = Field(
        default=None,
        description="The structured-output exit contract for this session.",
    )
    permissions: Union[PermissionsConfig_Input, None] = Field(
        default=None, description="What the session may touch, per minted credential."
    )
    skills: Union[list[SkillRef_Input], None] = Field(
        default=None, description="Skills installed for this session."
    )


